+package jdk.jfr.api.consumer.filestream;
+
+import java.io.IOException;
+import java.nio.file.Path;
+import java.util.concurrent.atomic.AtomicLong;
+
+import jdk.jfr.Recording;
+import jdk.jfr.consumer.EventStream;
+
+/**
+ * @test
+ * @summary Test EventStream::onClose(...)
+ * @requires vm.flagless
+ * @requires vm.hasJFR
+ * @library /test/lib
+ * @run main/othervm ${test.main.class}
+ */
+public class TestOnClose {
+
+    public static void main(String... args) throws Exception {
+        testCloseOnce();
+    }
+
+    private static void testCloseOnce() throws IOException {
+        Path file = Path.of("recording.jfr");
+        try (Recording r = new Recording()) {
+            r.start();
+            r.dump(file);
+        }
+        AtomicLong counter = new AtomicLong(0);
+        try (EventStream es = EventStream.openFile(file)) {
+            es.onClose(counter::incrementAndGet);
+            es.close();
+            // try-with-resources closes stream a second time
+        }
+        if (counter.get() != 1) {
+            throw new AssertionError("Expected close action to be run once");
+        }
+    }
+}

